class UnitOfWork {
  private dirty: Entity[] = [];

  registerDirty(entity: Entity) { this.dirty.push(entity); }

  async commit() {
    await db.transaction(async (tx) => {
      for (const entity of this.dirty) {
        await entity.save(tx); // all saved together, in ONE transaction
      }
    });
    this.dirty = [];
  }
}

async function transferFunds(from: Account, to: Account, amount: number, uow: UnitOfWork) {
  from.balance -= amount;
  to.balance += amount;
  uow.registerDirty(from);
  uow.registerDirty(to);
  await uow.commit(); // both save together, or neither does
}
